-- Maintenance gate and individual captain/lieutenant bypass.
create table if not exists public.system_settings(key text primary key,value jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id) on delete set null);
alter table public.system_settings enable row level security;revoke all on public.system_settings from anon,authenticated;grant select on public.system_settings to anon,authenticated;insert into public.system_settings(key,value) values('maintenance','{"enabled":false}'::jsonb) on conflict(key) do nothing;
create table if not exists public.maintenance_access(user_id uuid primary key references public.profiles(id) on delete cascade,granted_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now());alter table public.maintenance_access enable row level security;revoke all on public.maintenance_access from anon,authenticated;grant select on public.maintenance_access to authenticated;
create or replace function public.set_maintenance_mode(p_enabled boolean) returns void language plpgsql security definer set search_path=public,private as $$begin if not private.has_permission('access.manage') then raise exception 'forbidden';end if;insert into public.system_settings(key,value,updated_at,updated_by) values('maintenance',jsonb_build_object('enabled',p_enabled),now(),auth.uid()) on conflict(key) do update set value=excluded.value,updated_at=now(),updated_by=auth.uid();end$$;revoke all on function public.set_maintenance_mode(boolean) from public;grant execute on function public.set_maintenance_mode(boolean) to authenticated;
create or replace function public.set_maintenance_access(p_user uuid,p_enabled boolean) returns void language plpgsql security definer set search_path=public,private as $$declare r text;begin if not private.has_permission('access.manage') then raise exception 'forbidden';end if;select role into r from public.profiles where id=p_user;if r not in ('moderator','creator') then raise exception 'maintenance access only for captain or lieutenant';end if;if p_enabled then insert into public.maintenance_access(user_id,granted_by) values(p_user,auth.uid()) on conflict(user_id) do update set granted_by=auth.uid(),created_at=now();else delete from public.maintenance_access where user_id=p_user;end if;end$$;revoke all on function public.set_maintenance_access(uuid,boolean) from public;grant execute on function public.set_maintenance_access(uuid,boolean) to authenticated;
drop policy if exists "system settings readable" on public.system_settings;create policy "system settings readable" on public.system_settings for select using(true);drop policy if exists "maintenance grants self or access manager read" on public.maintenance_access;create policy "maintenance grants self or access manager read" on public.maintenance_access for select to authenticated using(user_id=auth.uid() or private.has_permission('access.manage'));